	scwin.checkVal = function() {
		return WebSquare.wUnit.getObjById('gridView1').getFocusedRowIndex() == 4;
	}
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getDomById('gridView2_cell_14_0').getAttribute('rowspan') == 2;
	}	
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
		WebSquare.wUnit.addCommand("pause", "400");		
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_0_0').click()");
		WebSquare.wUnit.addCommand("pause", "400");		
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_8_tab_tabs2').click()");
		WebSquare.wUnit.addCommand("pause", "400");	
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView2_cell_14_0').click()");
		WebSquare.wUnit.addCommand("pause", "400");			
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
